  const head=p.name.split(' ')[0],nameHit=head.length>=2&&!/^(카페|커피|중식|분식|국밥|치킨|피자|국수|라멘|초밥|우동|스시|빵|김밥|순대|포차|식당|한식|일식|양식|술집|호프)$/.test(head)&&q.includes(head);
  let hit=0,score=nameHit?1000:0;
  for(const t of terms)hit+=p.category.includes(t)?3:p.name.includes(t)||p.menu.some(m=>m.name.includes(t))?2:0;
  score+=(hit?150:0)+Math.min(hit,6)*5;
  if(meal&&/(카페|커피|베이커리|디저트|빙수|주스|요거트|버블티|칵테일|와인|호프|술집|주점|포장마차|떡|꽈배기|전통찻집)/.test(p.category))score-=400;
  const matched_menu=price?p.menu.filter(m=>m.price&&m.price<=price):p.menu;
