   lines.push('- '+day+' ('+(['오늘','내일','모레'][i]||'예보')+'): '+(DATA.wmo[code]||'정보 없음')+', 최저 '+min+'°C / 최고 '+max+'°C, 강수확률 '+prob+'%, 강수량 '+total+'mm, 자외선 '+d.uv_index_max[i]+', 바람 '+d.wind_speed_10m_max[i]+'km/h');
   for(const [a,b,label]of [[6,9,'출근길'],[12,15,'낮'],[18,21,'퇴근길']]){const xs=h.time.map((t,k)=>t.startsWith(day)&&+t.slice(11,13)>=a&&+t.slice(11,13)<=b?k:-1).filter(k=>k>=0);if(xs.length)lines.push('  · '+label+': '+Math.min(...xs.map(k=>h.temperature_2m[k]))+'~'+Math.max(...xs.map(k=>h.temperature_2m[k]))+'°C, 강수확률 최대 '+Math.max(...xs.map(k=>h.precipitation_probability[k]||0))+'%');}
